'use strict';
const user = {
  name: 'Ada',
  greet() {
    return 'Hi, ' + (this ? this.name : 'nobody');
  }
};

console.log(user.greet()); // 'Hi, Ada' (implicit binding)

const detached = user.greet;
try {
  console.log(detached()); // this is undefined -> throws or 'nobody'
} catch (e) {
  console.log('Error: this is undefined when detached');
}

