solution.code:
function myBind(fn, context) {
  return function (...args) {
    return fn.apply(context, args);
  };
}

const obj = { name: 'Ada' };
function greet(g) { return g + ', ' + this.name; }
const bound = myBind(greet, obj);
console.log(bound('Hello'));

brokenCode.code:
const timer = {
  seconds: 0,
  // BUG: arrow as a METHOD captures outer this, not timer
  tick: () => {
    this.seconds += 1;
    return this.seconds;
  }
};

console.log(timer.tick()); // NaN, and timer.seconds stays 0

solution.code:
const timer = {
  seconds: 0,
  tick() {            // regular method -> implicit binding to timer
    this.seconds += 1;
    return this.seconds;
  }
};

console.log(timer.tick()); // 1
console.log(timer.tick()); // 2

Function.prototype.myCall = function (context, ...args) {
  context = context || globalThis;
  const key = Symbol('fn');
  context[key] = this;          // implicit binding will set `this`
  const result = context[key](...args);
  delete context[key];
  return result;
};

function greet(g) { return g + ', ' + this.name; }
console.log(greet.myCall({ name: 'Ada' }, 'Hi')); // 'Hi, Ada'
